#!/bin/sh
#
# configure - RhapsodyUSB-x86
#

set -e

PREFIX="/usr/local"
CC="${CC:-gcc}"
LD="${LD:-ld}"
CFLAGS="${CFLAGS:-}"
LDFLAGS="${LDFLAGS:-}"

echo "Configuring RhapsodyUSB-x86..."
echo

#
# Check required tools
#

for tool in "$CC" "$LD" make; do
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "error: required tool '$tool' not found"
        exit 1
    fi
done

echo "Compiler: $CC"
echo "Linker:   $LD"

#
# Check compiler works
#

cat > conftest.c <<'EOF'
int main(void)
{
    return 0;
}
EOF

if "$CC" conftest.c -o conftest >/dev/null 2>&1; then
    echo "Compiler test: OK"
else
    echo "Compiler test: FAILED"
    rm -f conftest.c conftest
    exit 1
fi

rm -f conftest.c conftest

#
# Detect GNU89 support
#

cat > conftest.c <<'EOF'
int main(void)
{
    return 0;
}
EOF

if "$CC" -std=gnu89 conftest.c -o conftest >/dev/null 2>&1; then
    HAVE_GNU89=yes
    echo "GNU89 mode: OK"
else
    HAVE_GNU89=no
    echo "GNU89 mode: FAILED"
fi

rm -f conftest.c conftest

#
# Generate config.mk
#

cat > config.mk <<EOF
# Generated by configure

PREFIX = $PREFIX

CC = $CC
LD = $LD

USER_CFLAGS = $CFLAGS
USER_LDFLAGS = $LDFLAGS

HAVE_GNU89 = $HAVE_GNU89
EOF

echo
echo "Created config.mk"
echo
echo "Build commands:"
echo "  make check"
echo "  make"
echo
echo "Configuration complete."
